use strict;
use warnings;
use JSON::PP ();
use FSM::Adapter::IAL2::PPIF;
my $path = shift @ARGV;
open my $fh, '<', $path or die "Cannot read selected fixture: $!";
local $/; my $source = <$fh>; close $fh;
my $result = FSM::Adapter::IAL2::PPIF->new()->parse_source($source, $path);
print JSON::PP->new->canonical->pretty->encode({generated_ial1 => $result->{generated_ial1}, generated_ial0 => $result->{generated_ial0}});
